fn digit_char(d: Int) -> Str {
    if d == 0 {
        return "0"
    }
    if d == 1 {
        return "1"
    }
    if d == 2 {
        return "2"
    }
    if d == 3 {
        return "3"
    }
    if d == 4 {
        return "4"
    }
    if d == 5 {
        return "5"
    }
    if d == 6 {
        return "6"
    }
    if d == 7 {
        return "7"
    }
    if d == 8 {
        return "8"
    }
    return "9"
}

fn digits_str(n: Int) -> Str {
    if n == 0 {
        return "0"
    }
    var out = ""
    var m = n
    while m > 0 {
        let d = m - (m / 10) * 10
        out = digit_char(d) + out
        m = m / 10
    }
    return out
}

fn int_str(n: Int) -> Str {
    if n < 0 {
        return "-" + digits_str(0 - n)
    }
    return digits_str(n)
}

fn insert_sorted(acc: List[Int], x: Int) -> List[Int] {
    var out: List[Int] = []
    var placed = false
    for y in acc {
        if not placed and y >= x {
            if y > x {
                out = out.push(x)
            }
            placed = true
        }
        out = out.push(y)
    }
    if not placed {
        out = out.push(x)
    }
    return out
}

fn flush(out: Str, start: Int, prev: Int) -> Str {
    var o = out
    if o != "" {
        o = o + ","
    }
    if prev - start >= 2 {
        return o + int_str(start) + "-" + int_str(prev)
    }
    if prev - start == 1 {
        return o + int_str(start) + "," + int_str(prev)
    }
    return o + int_str(start)
}

pub fn ranges(xs: List[Int]) -> Str {
    var acc: List[Int] = []
    for x in xs {
        acc = insert_sorted(acc, x)
    }
    var out = ""
    var has_run = false
    var start = 0
    var prev = 0
    for y in acc {
        if not has_run {
            start = y
            prev = y
            has_run = true
        } else if y == prev + 1 {
            prev = y
        } else {
            out = flush(out: out, start: start, prev: prev)
            start = y
            prev = y
        }
    }
    if has_run {
        out = flush(out: out, start: start, prev: prev)
    }
    return out
}
